-- GENERATED by benchmarks/tpch/scripts/qualify_queries.py from ../queries — do not edit.
-- Mixed layout: dimensions in postgresql.tpch_mixed, facts in hive.tpch.
-- TPC-H Q17: Small-Quantity-Order Revenue — standard form
SELECT
    SUM(l_extendedprice) / 7.0 AS avg_yearly
FROM hive.tpch.lineitem
JOIN postgresql.tpch_mixed.part ON p_partkey = l_partkey
WHERE p_brand = 'Brand#23'
    AND p_container = 'MED BOX'
    AND l_quantity < (
        SELECT 0.2 * AVG(l_quantity)
        FROM hive.tpch.lineitem
        WHERE l_partkey = p_partkey
    )
